    dp = [[None] * n for _ in range(n)]

    def can_win(l, r):
        if dp[l][r] is not None:
            return dp[l][r]

        # If the substring is of length 1, the current player wins
        if l == r:
            dp[l][r] = True
            return True

        # Try to find a move for the current player
        for l_prime in range(l, -1, -1):
            for r_prime in range(r, n):
                if s[l_prime] < s[l] or (s[l_prime] == s[l] and s[r_prime] < s[r]):
                    if not can_win(l_prime, r_prime):
                        dp[l][r] = True
                        return True

        # If no winning move is found, the current player loses
        dp[l][r] = False
        return False

    results = []
    for k in range(n):
        if can_win(k, k):
            results.append("Ann")
        else:
            results.append("Mike")

    return results

